//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.MSG_NO_FILE = "기존첨부파일이 있습니다";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyListComiteDelibCaseSeq = "";
scwin.lastPosition = 0;
scwin.vListComiteDd = '';
scwin.file_flag = "N";
scwin.vScrenID = "ULDSTF06010.xml";
scwin.listComiteDelibCaseSeq = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_ShowCalendar = function(o) {
    popUpCalendar2(o);
};


// search function end
scwin.fn_save = function(jobType) {
    //2009.05.12 위원회일/철회일 필수 체크
    if (med_ListComiteDd.getValue() == "") {
        $c.win.alert("위원회일을 입력하여 주세요");
        med_ListComiteDd.focus();
        return false;
    }
    var check = scwin.fn_fileYnCheck();
    var vScrenProcTpCd;
    if (jobType == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    var cnt = dts_Cmt.getTotalRow();
    for (var i = 1; i < cnt + 1; i++) {
        var comiteCaseNm = dts_Cmt.getCellData(i, "COMITE_CASE_NM");
        var comiteCaseNo = dts_Cmt.getCellData(i, "COMITE_CASE_NO");
        var comiteCaseTpCd = dts_Cmt.getCellData(i, "COMITE_CASE_TP_CD");
        if (scwin.vListComiteDd != med_ListComiteDd.getValue()) {
            dts_Cmt.setCellData(i, "LIST_COMITE_DD", med_ListComiteDd.getValue());
        }
        if (comiteCaseNo == '') {
            $c.win.alert('[안건번호]가 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseTpCd == '') {
            $c.win.alert('[안건구분]이 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseNm == '') {
            $c.win.alert('[안건명]이 입력되지 않았습니다.');
            return false;
        }
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        if (scwin.strKeyListComiteDelibCaseSeq == "") {
            scwin.listComiteDelibCaseSeq = scwin.fn_getListComiteDelibCaseSeq();
            dts_ReqInf.insertRow();
            dts_ReqInf.setCellData(1, "LIST_COMITE_DELIB_CASE_SEQ", scwin.listComiteDelibCaseSeq);
            scwin.strKeyListComiteDelibCaseSeq = scwin.listComiteDelibCaseSeq;
        }
        tr_Save.Action = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelib";
        tr_Save.KeyName = "toinb_dataid4";
        tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf,I:pInpCmt=dts_Cmt,I:pFile=dts_fileList)";
        tr_Save.Post();
    } else if (!$c.cp.isModified(dts_ReqInf) && !$c.cp.isModified(dts_Cmt) && check == "Y") {
        tr_File.Action = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveFiledelib&LIST_COMITE_DELIB_CASE_SEQ=" + dts_ReqInf.getCellData(1, "LIST_COMITE_DELIB_CASE_SEQ");
        tr_File.KeyValue = "JSP(I:pFile=dts_fileList)";
        tr_File.Post();
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};


//파일첨부 삭제 여부
scwin.fn_fileYnCheck = function() {
    for (i = 1; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") != "") {
            scwin.file_flag = "Y";
        }
    }
    return scwin.file_flag;
};


//첨부파일 저장 
scwin.fn_fileInsert = function() {
    //if (dts_fileList.IsUpdated) 
    //{		    
    //alert(dts_fileList.Text);
    tr_File.Action = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveFiledelib&LIST_COMITE_DELIB_CASE_SEQ=" + dts_ReqInf.getCellData(1, "LIST_COMITE_DELIB_CASE_SEQ");
    tr_File.KeyValue = "JSP(I:pFile=dts_fileList)";
    tr_File.Post();
    $c.win.alert("2");
    //}

};



//첨부파일 조회
scwin.fn_fileSearch = function() {
    var url = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchFiledelib" + "&inputMessageId=COMITEDELIB_DATA_INOUT" + "&outputMessageId=COMITEDELIB_DATA_INOUT" + "&LIST_COMITE_DELIB_CASE_SEQ=" + dts_ReqInf.getCellData(1, "LIST_COMITE_DELIB_CASE_SEQ");
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.reset();
};

//
scwin.fn_txbLoad = function() {
    txb_file_name1.setValue("");
    txb_file_name2.setValue("");
    txb_file_name3.setValue("");
    txb_file_name4.setValue("");
    txb_file_name5.setValue("");
};


//첨부파일 읽기 
scwin.fn_read = function() {
    scwin.fn_txbLoad();
    tr_ReadFile.Action = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFiledelib&LIST_COMITE_DELIB_CASE_SEQ=" + dts_ReqInf.getCellData(1, "LIST_COMITE_DELIB_CASE_SEQ");
    tr_ReadFile.KeyValue = "JSP(O:pOutput=dts_fileList)";
    tr_ReadFile.Post();
};
scwin.fn_list_reqInf = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=COMITEDELIB_REQINF_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.comite.comitedelib.select.case" + "&{P}PARAM01=" + scwin.strKeyListComiteDelibCaseSeq;
    dts_ReqInf.DataID = encodeURI(url);
    dts_ReqInf.Reset();
};
scwin.fn_list_cmt = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=COMITEDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.comite.comitedelib.select.case" + "&{P}PARAM01=" + scwin.strKeyListComiteDelibCaseSeq;
    dts_Cmt.DataID = encodeURI(url);
    dts_Cmt.Reset();
};
scwin.fn_addNewCmt = function() {
    var listComiteDd = med_ListComiteDd.getValue();
    var listComiteRnd = $c.stf.getObjectValue(tbx_LIST_COMITE_RND);
    var listComiteRndExecYY = $c.stf.getObjectValue(tbx_LIST_COMITE_RND_EXEC_YY);
    if (listComiteDd == '') {
        $c.win.alert('위원회일을 입력해 주십시오');
        return;
    }
    if (listComiteRnd == "") {
        $c.win.alert('회차를 입력해 주십시오');
        return;
    }
    if (dts_Cmt.getTotalRow() > 0) {
        scwin.lastPosition = dts_Cmt.getCellData(dts_Cmt.getTotalRow(), "COMITE_CASE_NO");
    }
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_DELIB_CASE_SEQ", scwin.strKeyListComiteDelibCaseSeq);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_DD", listComiteDd);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_RND_EXEC_YY", listComiteRndExecYY);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_RND", listComiteRnd);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO", parseInt(scwin.lastPosition++));
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO_NM", "제" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO") + "호");
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_DTL_NO", '1');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD", '1');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_MAJAGNT_DEP_TP_CD", $c.stf.getObjectValue(rdo_COMITE_CASE_MAJAGNT_DEP_TP_CD));
    lastPostion = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "COMITE_CASE_NO");
};
scwin.fn_setKeyCtrOnAdd = function() {
    $c.lc.fn_setCtrWritable([med_ListComiteDd]);
};
scwin.fn_setKeyCtrOnUpd = function() {
    $c.lc.fn_setCtrReadOnly([med_ListComiteDd]);
};



//파일다운로드	
scwin.fn_filedown = function(attach_seq) {
    if (dts_fileList.getRowStatus(attach_seq) == 0 && dts_fileList.getCellData(attach_seq, "filename") != "") {
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "LIST_COMITE_DELIB_CASE_SEQ") + "&attach_seq=" + attach_seq + "&gubun=28";
    }
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.fn_deleteAll = function() {
    var vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    tr_Delete.Action = "/ComiteDelib.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=deleteCmtdelib";
    tr_Delete.KeyName = "toinb_dataid4";
    tr_Delete.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf,I:pInpCmt=dts_Cmt ,I:pFile=dts_fileList)";
    tr_Delete.Post();
};
scwin.fn_getListComiteDelibCaseSeq = function() {
    var new_list_comite_delib_case_seq = "";
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=COMITEDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.comite.comitedelib.select.seq";
    dts_param.DataID = encodeURI(url);
    dts_param.Reset();
    new_list_comite_delib_case_seq = dts_param.getCellData(1, "LIST_COMITE_DELIB_CASE_SEQ");
    return new_list_comite_delib_case_seq;
};
scwin.fn_deleteRow = function() {
    var count = dts_Cmt.getTotalRow();
    for (var j = 1; j <= count + 1; j++) {
        if (dts_Cmt.getCellData(j, "CHECK") == 'T') {
            $c.cp.removeRow(dts_Cmt, j);
        }
    }
};
scwin.fn_AddRow = function(attach_seq) {
    if (dts_ReqInf.getTotalRow() == 0) {
        $c.win.alert('안건을 등록해 주십시오');
        return;
    }
    var setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    dts_fileList.setRowPosition(attach_seq, 0);
    inf_find.open();
    if (inf_find.getValue() != "") {
        setArr[attach_seq - 1].setValue(inf_find.getValue());
    }
};
scwin.fn_DeleteRow = function(attach_seq) {
    var setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    setArr[attach_seq - 1].setValue("");
    dts_fileList.setRowPosition(attach_seq, 0);
    if (dts_fileList.getCellData(attach_seq, "filename") != "") {
        scwin.file_flag = "Y";
    }
    dts_fileList.setCellData(attach_seq, "fileinfo", "");
    dts_fileList.setCellData(attach_seq, "fileUrl", "");
    $c.cp.removeRow(dts_fileList, attach_seq);
    dts_fileList.insertRow(attach_seq - 1);
    dts_fileList.setCellData(attach_seq, "SEQ", attach_seq);
};
scwin.dts_Cmt_OnLoadCompleted = function(rowcount) {
    if (dts_Cmt.getTotalRow() > 0) {
        //fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
        scwin.lastPosition = dts_Cmt.getCellData(dts_Cmt.getTotalRow(), "COMITE_CASE_NO");
    } else {
        scwin.lastPosition = 0;
    }
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    if (dts_ReqInf.getTotalRow() > 0) {
        scwin.vListComiteDd = dts_ReqInf.getCellData(1, "LIST_COMITE_DD");
    }
    scwin.fn_read();
};
scwin.tr_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_Save_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    if (dts_Cmt.getTotalRow() > 0) {
        scwin.fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태

    }
    scwin.fn_list_reqInf();
    scwin.fn_list_cmt();
    scwin.fn_parentRefresh();
};
scwin.img_SetComiteDd_onclick = function() {
    /*if(strKeyListComiteDelibCaseSeq != ""){
      alert('위원회일은 수정할 수 없습니다');
	  return;
   }else{
		fn_ShowCalendar(med_ListComiteDd) ;
	}*/
    scwin.fn_ShowCalendar(med_ListComiteDd);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Save_onclick = function() {
    scwin.fn_save("I");
};
scwin.img_Delete_onclick = function() {
    scwin.fn_deleteAll();
};
scwin.btn_lineadd1_onclick = function() {
    scwin.fn_AddRow(1);
};
scwin.btn_lineadd2_onclick = function() {
    scwin.fn_AddRow(2);
};
scwin.btn_lineadd3_onclick = function() {
    scwin.fn_AddRow(3);
};
scwin.btn_lineadd4_onclick = function() {
    scwin.fn_AddRow(4);
};
scwin.btn_lineadd5_onclick = function() {
    scwin.fn_AddRow(5);
};
scwin.btn_linedelete1_onclick = function() {
    scwin.fn_DeleteRow(1);
};
scwin.btn_linedelete2_onclick = function() {
    scwin.fn_DeleteRow(2);
};
scwin.btn_linedelete3_onclick = function() {
    scwin.fn_DeleteRow(3);
};
scwin.btn_linedelete4_onclick = function() {
    scwin.fn_DeleteRow(4);
};
scwin.btn_linedelete5_onclick = function() {
    scwin.fn_DeleteRow(5);
};
scwin.btn_fileSave1_onclick = function() {
    scwin.fn_filedown("1");
};
scwin.btn_fileSave2_onclick = function() {
    scwin.fn_filedown("2");
};
scwin.btn_fileSave3_onclick = function() {
    scwin.fn_filedown("3");
};
scwin.btn_fileSave4_onclick = function() {
    scwin.fn_filedown("4");
};
scwin.btn_fileSave5_onclick = function() {
    scwin.fn_filedown("5");
};
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    var setArr = [txb_file_name1, txb_file_name2, txb_file_name3, txb_file_name4, txb_file_name5];
    if (rowcount > 0) {
        var k;
        for (var i = 0; i < rowcount; i++) {
            k = dts_fileList.getCellData(i + 1, "SEQ");
            setArr[k - 1].setValue(dts_fileList.getCellData(i + 1, "filename"));
            //if(dts_fileList.NameString(i+1, "filename") ==""){setBtn[i].disabled=true;}

        }
    }
    for (var i = rowcount; i < 5; i++) {
        dts_fileList.insertRow();
        dts_fileList.setCellData(i + 1, "SEQ", i + 1);
    }
};
scwin.tr_File_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_File_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_list_reqInf();
    scwin.fn_parentRefresh();
};
scwin.gform_onload = function() {
    $c.stf.showObj(panel_Term, false);
    var parentWin = $c.frame.path("../");
    scwin.strKeyListComiteDelibCaseSeq = parentWin.clickListComiteDelibCaseSeq;
    scwin.fn_list_reqInf();
    scwin.fn_list_cmt();
    if (scwin.strKeyListComiteDelibCaseSeq == "") {
        var dNow = new Date();
        $c.stf.setObjectValue(tbx_LIST_COMITE_RND_EXEC_YY, dNow.getYear());
    } else {
        //tbx_LIST_COMITE_RND_EXEC_YY.readOnly = true;

        //tbx_LIST_COMITE_RND.readOnly = true;

    }
};
scwin.img_row_append_onclick = function() {
    scwin.fn_addNewCmt();
};
scwin.img_row_delete_onclick = function() {
    var count = dts_Cmt.getTotalRow();
    for (var j = count; j > 0; j--) {
        if (dts_Cmt.getCellData(j, "CHECK") == 'T') {
            $c.cp.removeRow(dts_Cmt, j);
            scwin.fn_deleteRow();
        }
    }
};
scwin.grd_cmt_OnHeadCheckClick = function(col, colid, bCheck) {
    var count = dts_Cmt.getTotalRow();
    if (bCheck == '1') {
        for (var j = 1; j <= count + 1; j++) {
            dts_Cmt.setCellData(j, "CHECK", 'T');
        }
    } else {
        for (var j = 1; j <= count + 1; j++) {
            dts_Cmt.setCellData(j, "CHECK", '');
        }
    }
};
scwin.tr_Delete_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.strKeyListComiteDelibCaseSeq = '';
    scwin.fn_list_reqInf();
    scwin.fn_list_cmt();
    scwin.fn_parentRefresh();
    var dNow = new Date();
    $c.stf.setObjectValue(tbx_LIST_COMITE_RND_EXEC_YY, dNow.getYear());
};
scwin.rdo_COMITE_CASE_MAJAGNT_DEP_TP_CD_OnSelChange = function() {
    for (var i = 1; i <= dts_Cmt.getTotalRow(); i++) {
        dts_Cmt.setCellData(i, "COMITE_CASE_MAJAGNT_DEP_TP_CD", $c.stf.getObjectValue(rdo_COMITE_CASE_MAJAGNT_DEP_TP_CD));
    }
};
scwin.tbx_LIST_COMITE_RND_EXEC_YY_onchange = function() {
    for (var i = 1; i <= dts_Cmt.getTotalRow(); i++) {
        dts_Cmt.setCellData(i, "LIST_COMITE_RND_EXEC_YY", $c.stf.getObjectValue(tbx_LIST_COMITE_RND_EXEC_YY));
    }
};
scwin.tbx_LIST_COMITE_RND_onchange = function() {
    for (var i = 1; i <= dts_Cmt.getTotalRow(); i++) {
        dts_Cmt.setCellData(i, "LIST_COMITE_RND", $c.stf.getObjectValue(tbx_LIST_COMITE_RND));
    }
};
scwin.grd_cmt_CanColumnPosChange = function(row, colid) {
    return true;
};
